﻿using UnityEngine;
using System.Collections.Generic;

public class PlayerMovement
{
    private const float Gravity = -1.0f;

    public bool IsOnGround { get; set; }

    private Vector3 currentVelocity;

    public Vector3 Update()
    {
        if (IsOnGround)
