namespace MediaCentreServer.Controllers
{
	// Controller for running an application.
	public class RunController : ApiController
	{
		// POST /api/run?path=...
		public HttpResponseMessage Post(string path)
		{
			var startInfo = new ProcessStartInfo(path);
			try
